import{_ as e,o,c as t,a2 as l}from"./chunks/framework.C0KMm31j.js";const r="/Nav2ArticlesSite/article-assets/2026-07-17/nav2_navfn_cover.png",n="/Nav2ArticlesSite/article-assets/2026-07-17/nav2_navfn_01_architecture.png",i="/Nav2ArticlesSite/article-assets/2026-07-17/nav2_navfn_02_lifecycle.png",c="/Nav2ArticlesSite/article-assets/2026-07-17/nav2_navfn_03_interfaces.png",d="/Nav2ArticlesSite/article-assets/2026-07-17/nav2_navfn_04_cost_conversion.png",h="/Nav2ArticlesSite/article-assets/2026-07-17/nav2_navfn_05_propagation.png",s="/Nav2ArticlesSite/article-assets/2026-07-17/nav2_navfn_06_path_outcomes.png",q=JSON.parse('{"title":"Dijkstra 还是 A*，一张代价地图如何长出路径？拆解 nav2_navfn_planner 势场搜索全数据流","description":"给机器人一个起点、一个目标点和一张代价地图，怎样才能得到一条绕开障碍的全局路径？","frontmatter":{"title":"Dijkstra 还是 A*，一张代价地图如何长出路径？拆解 `nav2_navfn_planner` 势场搜索全数据流","description":"给机器人一个起点、一个目标点和一张代价地图，怎样才能得到一条绕开障碍的全局路径？","date":"2026-07-17","topic":"Nav2 工程实践","section":"二 · 全局规划与路径搜索","readingTime":15,"source":"2026-07-17/nav2_navfn_full_dataflow.md","status":"published","cover":"/article-assets/2026-07-17/nav2_navfn_cover.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/nav2/nav2-navfn-full-dataflow"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"Dijkstra 还是 A*，一张代价地图如何长出路径？拆解 `nav2_navfn_planner` 势场搜索全数据流"}],["meta",{"property":"og:description","content":"给机器人一个起点、一个目标点和一张代价地图，怎样才能得到一条绕开障碍的全局路径？"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/nav2/nav2-navfn-full-dataflow"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-07-17/nav2_navfn_cover.png"}],["meta",{"property":"article:published_time","content":"2026-07-17"}],["meta",{"name":"twitter:title","content":"Dijkstra 还是 A*，一张代价地图如何长出路径？拆解 `nav2_navfn_planner` 势场搜索全数据流"}],["meta",{"name":"twitter:description","content":"给机器人一个起点、一个目标点和一张代价地图，怎样才能得到一条绕开障碍的全局路径？"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-07-17/nav2_navfn_cover.png"}]],"prev":{"text":"Nav2 为什么要把导航拆成任务？拆解 Navigation 2 Overview 的任务架构、环境模型与 Behavior Tree","link":"/nav2/navigation2-overview-design-analysis"},"next":{"text":"目标点如何穿过障碍变成一条路？拆解 `nav2_planner` 的双 Action 与全局规划数据流","link":"/nav2/nav2-planner-full-dataflow"}},"headers":[],"relativePath":"nav2/nav2-navfn-full-dataflow.md","filePath":"nav2/nav2-navfn-full-dataflow.md","lastUpdated":null}'),p={name:"nav2/nav2-navfn-full-dataflow.md"};function u(_,a,v,f,P,b){return o(),t("div",null,[...a[0]||(a[0]=[l('<h1 id="dijkstra-还是-a-一张代价地图如何长出路径-拆解-nav2-navfn-planner-势场搜索全数据流" tabindex="-1">Dijkstra 还是 A*，一张代价地图如何长出路径？拆解 <code>nav2_navfn_planner</code> 势场搜索全数据流 <a class="header-anchor" href="#dijkstra-还是-a-一张代价地图如何长出路径-拆解-nav2-navfn-planner-势场搜索全数据流" aria-label="Permalink to &quot;Dijkstra 还是 A*，一张代价地图如何长出路径？拆解 `nav2_navfn_planner` 势场搜索全数据流&quot;">​</a></h1><p><img src="'+r+'" alt="封面：nav2_navfn_planner 势场搜索全数据流"></p><p>给机器人一个起点、一个目标点和一张代价地图，怎样才能得到一条绕开障碍的全局路径？</p><p>很多人会把答案简单概括成“跑一次 Dijkstra 或 A*”。但在 Nav2 的 <code>nav2_navfn_planner</code> 中，真正的数据链路还包括插件加载、Lifecycle 资源管理、代价重编码、势场传播、目标容差搜索、梯度路径提取、坐标还原和末姿态修正。</p><p>本文基于当前工程中的 <code>nav2_navfn_planner 1.1.20</code> 源码，完整拆解这个经典规划器的所有调用、状态和输入输出数据流。</p><hr><h2 id="一、先给结论-navfn-不是节点-而是-planner-server-里的算法插件" tabindex="-1">一、先给结论：NavFn 不是节点，而是 Planner Server 里的算法插件 <a class="header-anchor" href="#一、先给结论-navfn-不是节点-而是-planner-server-里的算法插件" aria-label="Permalink to &quot;一、先给结论：NavFn 不是节点，而是 Planner Server 里的算法插件&quot;">​</a></h2><p><code>nav2_navfn_planner</code> 不创建独立 ROS 2 节点，也不直接提供 Topic、Service 或 Action。</p><p>它构建的是共享库 <code>nav2_navfn_planner</code>，通过 pluginlib 导出：</p><ul><li>Plugin Name：<code>nav2_navfn_planner/NavfnPlanner</code>。</li><li>C++ Type：<code>nav2_navfn_planner::NavfnPlanner</code>。</li><li>Base Class：<code>nav2_core::GlobalPlanner</code>。</li></ul><p>上游 <code>PlannerServer</code> 收到 <code>/compute_path_to_pose</code> 或 <code>/compute_path_through_poses</code> 请求后，负责获取机器人位姿、处理 TF、选择 Planner ID，再在同一进程中调用插件的：</p><p><code>createPlan(start, goal) -&gt; nav_msgs::msg::Path</code></p><p><img src="'+n+'" alt="图 1：NavFn 插件在全局规划调用链中的位置"></p><p>因此，本包的职责边界非常清楚：</p><ul><li>Planner Server 管理 ROS 接口、全局代价地图和插件调度。</li><li>NavfnPlanner 包装层负责坐标与参数适配、容差选点和 Path 封装。</li><li>NavFn 内核负责代价转换、Dijkstra／A* 势场传播和梯度路径提取。</li></ul><p>它不负责定位，不负责 TF 转换，不负责局部控制，也不直接发布规划结果。</p><hr><h2 id="二、两层实现-外层是-nav2-插件-内层是-navfn-势场内核" tabindex="-1">二、两层实现：外层是 Nav2 插件，内层是 NavFn 势场内核 <a class="header-anchor" href="#二、两层实现-外层是-nav2-插件-内层是-navfn-势场内核" aria-label="Permalink to &quot;二、两层实现：外层是 Nav2 插件，内层是 NavFn 势场内核&quot;">​</a></h2><p>本包主要由两组类组成。</p><h3 id="_2-1-外层-navfnplanner" tabindex="-1">2.1 外层 <code>NavfnPlanner</code> <a class="header-anchor" href="#_2-1-外层-navfnplanner" aria-label="Permalink to &quot;2.1 外层 `NavfnPlanner`&quot;">​</a></h3><p>它实现 <code>nav2_core::GlobalPlanner</code> 接口，持有：</p><ul><li>父 Lifecycle Node 弱引用。</li><li>TF Buffer 指针。</li><li>Global Costmap 裸指针。</li><li>Global Frame 名称和 Plugin ID。</li><li>四个插件参数。</li><li>一个 <code>std::unique_ptr&lt;NavFn&gt;</code> 内核。</li></ul><p>虽然 <code>configure()</code> 会保存 TF Buffer，但当前实现中没有任何 <code>tf_-&gt;transform()</code> 或 <code>lookupTransform()</code> 调用。它假设传入的起点和目标已经由 Planner Server 转换到 Global Costmap Frame。</p><h3 id="_2-2-内层-navfn" tabindex="-1">2.2 内层 <code>NavFn</code> <a class="header-anchor" href="#_2-2-内层-navfn" aria-label="Permalink to &quot;2.2 内层 `NavFn`&quot;">​</a></h3><p>它维护栅格算法需要的全部数组：</p><ul><li><code>costarr</code>：转换后的通行代价。</li><li><code>potarr</code>：从传播源扩展出的导航势能。</li><li><code>pending</code>：单元是否已经在等待队列中。</li><li><code>gradx</code>、<code>grady</code>：势场梯度缓存。</li><li><code>pathx</code>、<code>pathy</code>：亚栅格路径点。</li><li><code>curP</code>、<code>nextP</code>、<code>overP</code>：三组波前优先级缓冲区。</li></ul><p>外层回答“怎么接入 Nav2”，内层回答“怎么从代价地图算出路径”。</p><hr><h2 id="三、第一类状态-插件生命周期决定资源何时存在" tabindex="-1">三、第一类状态：插件生命周期决定资源何时存在 <a class="header-anchor" href="#三、第一类状态-插件生命周期决定资源何时存在" aria-label="Permalink to &quot;三、第一类状态：插件生命周期决定资源何时存在&quot;">​</a></h2><p>NavfnPlanner 不是 Lifecycle Node，但它的四个生命周期函数由 Planner Server 的 Lifecycle 状态驱动。</p><p><img src="'+i+'" alt="图 2：NavfnPlanner 生命周期与内部资源状态"></p><h3 id="_3-1-configure-建立规划上下文" tabindex="-1">3.1 <code>configure()</code>：建立规划上下文 <a class="header-anchor" href="#_3-1-configure-建立规划上下文" aria-label="Permalink to &quot;3.1 `configure()`：建立规划上下文&quot;">​</a></h3><p>Planner Server 把父节点、Plugin ID、TF Buffer 和 Global Costmap 传进来。插件随后：</p><h4 id="_3-1-1-保存-costmap-指针和-global-frame" tabindex="-1">3.1.1 保存 Costmap 指针和 Global Frame <a class="header-anchor" href="#_3-1-1-保存-costmap-指针和-global-frame" aria-label="Permalink to &quot;3.1.1 保存 Costmap 指针和 Global Frame&quot;">​</a></h4><h4 id="_3-1-2-获取父节点的-clock-与-logger" tabindex="-1">3.1.2 获取父节点的 Clock 与 Logger <a class="header-anchor" href="#_3-1-2-获取父节点的-clock-与-logger" aria-label="Permalink to &quot;3.1.2 获取父节点的 Clock 与 Logger&quot;">​</a></h4><h4 id="_3-1-3-声明并读取四个参数" tabindex="-1">3.1.3 声明并读取四个参数 <a class="header-anchor" href="#_3-1-3-声明并读取四个参数" aria-label="Permalink to &quot;3.1.3 声明并读取四个参数&quot;">​</a></h4><h4 id="_3-1-4-按当前-costmap-尺寸创建-navfn-内核" tabindex="-1">3.1.4 按当前 Costmap 尺寸创建 NavFn 内核 <a class="header-anchor" href="#_3-1-4-按当前-costmap-尺寸创建-navfn-内核" aria-label="Permalink to &quot;3.1.4 按当前 Costmap 尺寸创建 NavFn 内核&quot;">​</a></h4><h3 id="_3-2-activate-打开动态参数入口" tabindex="-1">3.2 <code>activate()</code>：打开动态参数入口 <a class="header-anchor" href="#_3-2-activate-打开动态参数入口" aria-label="Permalink to &quot;3.2 `activate()`：打开动态参数入口&quot;">​</a></h3><p>插件注册 <code>add_on_set_parameters_callback()</code>。从这一刻起，四个插件参数可以在运行时更新。</p><h3 id="_3-3-deactivate-关闭动态参数入口" tabindex="-1">3.3 <code>deactivate()</code>：关闭动态参数入口 <a class="header-anchor" href="#_3-3-deactivate-关闭动态参数入口" aria-label="Permalink to &quot;3.3 `deactivate()`：关闭动态参数入口&quot;">​</a></h3><p>插件释放回调句柄，停止接收动态参数更新，但 NavFn 数组仍然保留。</p><h3 id="_3-4-cleanup-释放规划内核" tabindex="-1">3.4 <code>cleanup()</code>：释放规划内核 <a class="header-anchor" href="#_3-4-cleanup-释放规划内核" aria-label="Permalink to &quot;3.4 `cleanup()`：释放规划内核&quot;">​</a></h3><p>插件执行 <code>planner_.reset()</code>，NavFn 的 Cost Array、Potential Array、Gradient Array、Path Array 和三个优先级缓冲区随之释放。</p><hr><h2 id="四、输入输出接口-没有-ros-通信接口-只有一次进程内函数调用" tabindex="-1">四、输入输出接口：没有 ROS 通信接口，只有一次进程内函数调用 <a class="header-anchor" href="#四、输入输出接口-没有-ros-通信接口-只有一次进程内函数调用" aria-label="Permalink to &quot;四、输入输出接口：没有 ROS 通信接口，只有一次进程内函数调用&quot;">​</a></h2><p><img src="'+c+'" alt="图 3：NavfnPlanner 进程内输入输出接口"></p><h3 id="_4-1-直接输入-start-pose" tabindex="-1">4.1 直接输入：Start Pose <a class="header-anchor" href="#_4-1-直接输入-start-pose" aria-label="Permalink to &quot;4.1 直接输入：Start Pose&quot;">​</a></h3><p>类型是 <code>geometry_msgs::msg::PoseStamped</code>。</p><p>坐标应当已经处于 Global Costmap Frame。插件在常规分支中只读取 Pose，不检查 <code>header.frame_id</code>，也不执行 TF 转换。</p><h3 id="_4-2-直接输入-goal-pose" tabindex="-1">4.2 直接输入：Goal Pose <a class="header-anchor" href="#_4-2-直接输入-goal-pose" aria-label="Permalink to &quot;4.2 直接输入：Goal Pose&quot;">​</a></h3><p>同样是 <code>geometry_msgs::msg::PoseStamped</code>，并假设已转换到全局坐标系。</p><p>目标的 XY 用于搜索，目标 Orientation 用于默认末姿态；如果启用 <code>use_final_approach_orientation</code>，末姿态会改成路径最后一段的切线方向。</p><h3 id="_4-3-环境输入-global-costmap" tabindex="-1">4.3 环境输入：Global Costmap <a class="header-anchor" href="#_4-3-环境输入-global-costmap" aria-label="Permalink to &quot;4.3 环境输入：Global Costmap&quot;">​</a></h3><p>插件从 <code>Costmap2DROS</code> 取得底层 <code>Costmap2D*</code>。每次常规规划时，在 Costmap Mutex 保护下读取 Char Map，并转换为 NavFn 私有的 Cost Array。</p><h3 id="_4-4-配置输入-四个参数" tabindex="-1">4.4 配置输入：四个参数 <a class="header-anchor" href="#_4-4-配置输入-四个参数" aria-label="Permalink to &quot;4.4 配置输入：四个参数&quot;">​</a></h3><ul><li><code>tolerance</code>：默认 <code>0.5</code> m。</li><li><code>use_astar</code>：默认 <code>false</code>。</li><li><code>allow_unknown</code>：默认 <code>true</code>。</li><li><code>use_final_approach_orientation</code>：默认 <code>false</code>。</li></ul><h3 id="_4-5-唯一直接输出-path" tabindex="-1">4.5 唯一直接输出：Path <a class="header-anchor" href="#_4-5-唯一直接输出-path" aria-label="Permalink to &quot;4.5 唯一直接输出：Path&quot;">​</a></h3><p>返回 <code>nav_msgs::msg::Path</code>：</p><ul><li><code>header.stamp</code> 使用父节点 Clock 的当前时间。</li><li><code>header.frame_id</code> 使用 Global Costmap Frame。</li><li><code>poses</code> 按真实机器人起点到目标方向排列。</li></ul><p>如果失败，插件不抛出规划异常，而是返回 <code>poses</code> 为空的 Path。Planner Server 再把空路径转换成上层 Action 的失败结果。</p><hr><h2 id="五、代价转换-navfn-并不直接拿-ros-cost-值传播" tabindex="-1">五、代价转换：NavFn 并不直接拿 ROS Cost 值传播 <a class="header-anchor" href="#五、代价转换-navfn-并不直接拿-ros-cost-值传播" aria-label="Permalink to &quot;五、代价转换：NavFn 并不直接拿 ROS Cost 值传播&quot;">​</a></h2><p>Global Costmap 的 Char Map 进入 <code>NavFn::setCostmap()</code> 后，会先变成 NavFn 自己的代价数组。</p><p><img src="'+d+'" alt="图 4：ROS Costmap 到 NavFn Cost Array 的转换"></p><h3 id="_5-1-普通栅格-0-252" tabindex="-1">5.1 普通栅格 <code>0..252</code> <a class="header-anchor" href="#_5-1-普通栅格-0-252" aria-label="Permalink to &quot;5.1 普通栅格 `0..252`&quot;">​</a></h3><p>转换公式是：</p><p><code>navfn_cost = 50 + 0.8 × ros_cost</code></p><p>这意味着自由空间也不是零，而是从 <code>COST_NEUTRAL=50</code> 开始。越靠近膨胀障碍，传播代价越大，全局路径越倾向远离高代价区。</p><h3 id="_5-2-inscribed-与-lethal-栅格" tabindex="-1">5.2 Inscribed 与 Lethal 栅格 <a class="header-anchor" href="#_5-2-inscribed-与-lethal-栅格" aria-label="Permalink to &quot;5.2 Inscribed 与 Lethal 栅格&quot;">​</a></h3><p>ROS 值 <code>253</code> 和 <code>254</code> 都转为 <code>COST_OBS=254</code>，势场不会进入这些单元。</p><h3 id="_5-3-unknown-栅格-255" tabindex="-1">5.3 Unknown 栅格 <code>255</code> <a class="header-anchor" href="#_5-3-unknown-栅格-255" aria-label="Permalink to &quot;5.3 Unknown 栅格 `255`&quot;">​</a></h3><p>当 <code>allow_unknown=true</code> 时，未知单元转为 <code>253</code>：仍可传播，但代价非常高。</p><p>当 <code>allow_unknown=false</code> 时，未知单元保持障碍代价 <code>254</code>，规划不能穿越。</p><p>因此，“允许未知空间”不等于“把未知空间当自由空间”，而是把它当成最后才考虑的高风险通道。</p><hr><h2 id="六、第二类状态-一次规划请求怎样流过整个算法" tabindex="-1">六、第二类状态：一次规划请求怎样流过整个算法 <a class="header-anchor" href="#六、第二类状态-一次规划请求怎样流过整个算法" aria-label="Permalink to &quot;六、第二类状态：一次规划请求怎样流过整个算法&quot;">​</a></h2><h3 id="_6-1-检查内核尺寸" tabindex="-1">6.1 检查内核尺寸 <a class="header-anchor" href="#_6-1-检查内核尺寸" aria-label="Permalink to &quot;6.1 检查内核尺寸&quot;">​</a></h3><p><code>createPlan()</code> 先比较 NavFn 的 <code>nx／ny</code> 与当前 Costmap 尺寸。尺寸变化时重新创建内部数组。</p><p>但当前常规分支进入 <code>makePlan()</code> 后还会无条件调用一次 <code>setNavArr()</code>，即使尺寸没有变化，也会重新分配 Cost、Potential、Pending 和 Gradient 数组。</p><h3 id="_6-2-处理-start-与-goal-重合" tabindex="-1">6.2 处理 Start 与 Goal 重合 <a class="header-anchor" href="#_6-2-处理-start-与-goal-重合" aria-label="Permalink to &quot;6.2 处理 Start 与 Goal 重合&quot;">​</a></h3><p>如果起终点 XY 完全相同，插件直接返回只包含一个 Pose 的 Path。</p><ul><li>该栅格是 Lethal Obstacle：返回空 Path。</li><li>默认模式：单 Pose 使用 Goal Orientation。</li><li><code>use_final_approach_orientation=true</code>：保留 Start Orientation，避免控制器为了目标角度原地旋转。</li></ul><h3 id="_6-3-验证起点并清除机器人单元" tabindex="-1">6.3 验证起点并清除机器人单元 <a class="header-anchor" href="#_6-3-验证起点并清除机器人单元" aria-label="Permalink to &quot;6.3 验证起点并清除机器人单元&quot;">​</a></h3><p>常规分支把 Start World 坐标转换为 Map 坐标。离开 Global Costmap 立即失败。</p><p>随后 <code>clearRobotCell()</code> 会把机器人所在的共享 Costmap 栅格直接改成 <code>FREE_SPACE</code>，避免机器人因自身障碍痕迹而无法起步。</p><p>要注意，这不是只修改 NavFn 私有副本，而是修改 Planner Server 持有的底层 Global Costmap。</p><h3 id="_6-4-锁定并复制-costmap" tabindex="-1">6.4 锁定并复制 Costmap <a class="header-anchor" href="#_6-4-锁定并复制-costmap" aria-label="Permalink to &quot;6.4 锁定并复制 Costmap&quot;">​</a></h3><p>插件获取 Costmap Mutex，调用 <code>setNavArr()</code> 和 <code>setCostmap()</code>，把当前 Char Map 转换到私有 <code>costarr</code>，然后立即释放锁。</p><p>后面的势场传播和路径提取不再占用 Costmap Mutex，因此地图更新线程可以继续运行；本次规划使用的是刚刚复制下来的地图快照。</p><h3 id="_6-5-转换-goal" tabindex="-1">6.5 转换 Goal <a class="header-anchor" href="#_6-5-转换-goal" aria-label="Permalink to &quot;6.5 转换 Goal&quot;">​</a></h3><p>Goal 离开 Global Costmap 时直接失败。转换成功后进入势场传播。</p><hr><h2 id="七、最容易看反的一段-内部-start-与-goal-为什么交换了" tabindex="-1">七、最容易看反的一段：内部 Start 与 Goal 为什么交换了 <a class="header-anchor" href="#七、最容易看反的一段-内部-start-与-goal-为什么交换了" aria-label="Permalink to &quot;七、最容易看反的一段：内部 Start 与 Goal 为什么交换了&quot;">​</a></h2><h3 id="_7-1-设置反转后的内部起终点" tabindex="-1">7.1 设置反转后的内部起终点 <a class="header-anchor" href="#_7-1-设置反转后的内部起终点" aria-label="Permalink to &quot;7.1 设置反转后的内部起终点&quot;">​</a></h3><ul><li><code>NavFn::setStart(map_goal)</code>。</li><li><code>NavFn::setGoal(map_start)</code>。</li></ul><p>也就是说，NavFn 内部的 Start 是真实目标，内部的 Goal 是真实机器人起点。</p><p><img src="'+h+'" alt="图 5：Dijkstra／A* 势场传播与内部起终点反转"></p><p>这不是把最终 Path 算反了，而是 NavFn 势场的实现约定。</p><h3 id="_7-2-setupnavfn-把内部-goal-势能设为零" tabindex="-1">7.2 <code>setupNavFn()</code> 把内部 Goal 势能设为零 <a class="header-anchor" href="#_7-2-setupnavfn-把内部-goal-势能设为零" aria-label="Permalink to &quot;7.2 `setupNavFn()` 把内部 Goal 势能设为零&quot;">​</a></h3><h3 id="_7-3-波前从真实机器人起点向外扩散" tabindex="-1">7.3 波前从真实机器人起点向外扩散 <a class="header-anchor" href="#_7-3-波前从真实机器人起点向外扩散" aria-label="Permalink to &quot;7.3 波前从真实机器人起点向外扩散&quot;">​</a></h3><h3 id="_7-4-判断真实目标与机器人起点是否连通" tabindex="-1">7.4 判断真实目标与机器人起点是否连通 <a class="header-anchor" href="#_7-4-判断真实目标与机器人起点是否连通" aria-label="Permalink to &quot;7.4 判断真实目标与机器人起点是否连通&quot;">​</a></h3><p>当真实目标获得有限势能时，说明它与机器人起点连通。</p><h3 id="_7-5-calcpath-从真实目标沿势能下降方向回到真实起点" tabindex="-1">7.5 <code>calcPath()</code> 从真实目标沿势能下降方向回到真实起点 <a class="header-anchor" href="#_7-5-calcpath-从真实目标沿势能下降方向回到真实起点" aria-label="Permalink to &quot;7.5 `calcPath()` 从真实目标沿势能下降方向回到真实起点&quot;">​</a></h3><h3 id="_7-6-包装层逆序读取路径点" tabindex="-1">7.6 包装层逆序读取路径点 <a class="header-anchor" href="#_7-6-包装层逆序读取路径点" aria-label="Permalink to &quot;7.6 包装层逆序读取路径点&quot;">​</a></h3><p>输出仍然是机器人起点到目标。</p><p>理解这次“双重反转”，才能正确阅读后面的势场和路径数组。</p><hr><h2 id="八、dijkstra-与-a-势能计算相同-入队优先级不同" tabindex="-1">八、Dijkstra 与 A*：势能计算相同，入队优先级不同 <a class="header-anchor" href="#八、dijkstra-与-a-势能计算相同-入队优先级不同" aria-label="Permalink to &quot;八、Dijkstra 与 A*：势能计算相同，入队优先级不同&quot;">​</a></h2><h3 id="_8-1-初始化传播状态" tabindex="-1">8.1 初始化传播状态 <a class="header-anchor" href="#_8-1-初始化传播状态" aria-label="Permalink to &quot;8.1 初始化传播状态&quot;">​</a></h3><p>两种模式都会先执行 <code>setupNavFn(true)</code>。</p><h4 id="_8-1-1-把全部-potarr-设为-pot-high-1e10" tabindex="-1">8.1.1 把全部 <code>potarr</code> 设为 <code>POT_HIGH=1e10</code> <a class="header-anchor" href="#_8-1-1-把全部-potarr-设为-pot-high-1e10" aria-label="Permalink to &quot;8.1.1 把全部 `potarr` 设为 `POT_HIGH=1e10`&quot;">​</a></h4><h4 id="_8-1-2-清零梯度缓存和-pending-标记" tabindex="-1">8.1.2 清零梯度缓存和 Pending 标记 <a class="header-anchor" href="#_8-1-2-清零梯度缓存和-pending-标记" aria-label="Permalink to &quot;8.1.2 清零梯度缓存和 Pending 标记&quot;">​</a></h4><h4 id="_8-1-3-把地图最外圈强制设为障碍" tabindex="-1">8.1.3 把地图最外圈强制设为障碍 <a class="header-anchor" href="#_8-1-3-把地图最外圈强制设为障碍" aria-label="Permalink to &quot;8.1.3 把地图最外圈强制设为障碍&quot;">​</a></h4><h4 id="_8-1-4-初始化-curp、nextp、overp-三个缓冲区" tabindex="-1">8.1.4 初始化 <code>curP</code>、<code>nextP</code>、<code>overP</code> 三个缓冲区 <a class="header-anchor" href="#_8-1-4-初始化-curp、nextp、overp-三个缓冲区" aria-label="Permalink to &quot;8.1.4 初始化 `curP`、`nextP`、`overP` 三个缓冲区&quot;">​</a></h4><h4 id="_8-1-5-把传播源势能设为零并初始化当前缓冲区" tabindex="-1">8.1.5 把传播源势能设为零并初始化当前缓冲区 <a class="header-anchor" href="#_8-1-5-把传播源势能设为零并初始化当前缓冲区" aria-label="Permalink to &quot;8.1.5 把传播源势能设为零并初始化当前缓冲区&quot;">​</a></h4><p>传播源的上下左右邻居随后加入当前缓冲区。</p><h3 id="_8-2-dijkstra-模式" tabindex="-1">8.2 Dijkstra 模式 <a class="header-anchor" href="#_8-2-dijkstra-模式" aria-label="Permalink to &quot;8.2 Dijkstra 模式&quot;">​</a></h3><p><code>updateCell()</code> 根据上下左右四个邻居中的最低势能，以及当前栅格通行代价，用二次近似更新平面波势能。</p><p>它不加入到目标的启发距离，波前按累计代价向四周扩展。</p><h3 id="_8-3-a-模式" tabindex="-1">8.3 A* 模式 <a class="header-anchor" href="#_8-3-a-模式" aria-label="Permalink to &quot;8.3 A* 模式&quot;">​</a></h3><p><code>updateCellAstar()</code> 使用相同的势能更新公式，但在决定单元进入哪个优先级缓冲区时，额外叠加到内部 Start，也就是真实目标的欧氏距离启发项。</p><p>因此 A* 通常访问更少单元；两者最终都在同一个 <code>potarr</code> 上进行梯度取路。</p><h3 id="_8-4-三个优先级缓冲区" tabindex="-1">8.4 三个优先级缓冲区 <a class="header-anchor" href="#_8-4-三个优先级缓冲区" aria-label="Permalink to &quot;8.4 三个优先级缓冲区&quot;">​</a></h3><ul><li><code>curP</code>：当前阈值内正在处理的单元。</li><li><code>nextP</code>：当前单元更新后，可在本阈值继续推进的邻居。</li><li><code>overP</code>：势能超过当前阈值，留到后续处理的单元。</li></ul><p>当当前层清空时，<code>curT</code> 增加 <code>priInc</code>，Overflow Buffer 接管下一层传播。</p><hr><h2 id="九、目标被占用时-tolerance-到底怎样选替代终点" tabindex="-1">九、目标被占用时，<code>tolerance</code> 到底怎样选替代终点 <a class="header-anchor" href="#九、目标被占用时-tolerance-到底怎样选替代终点" aria-label="Permalink to &quot;九、目标被占用时，`tolerance` 到底怎样选替代终点&quot;">​</a></h2><p>势场完成后，插件先检查原始 Goal 的 Potential。</p><p>如果小于 <code>POT_HIGH</code>，原始目标可达，直接作为 Path 终点。</p><p>如果不可达，插件在：</p><ul><li>X：<code>goal.x - tolerance</code> 到 <code>goal.x + tolerance</code>。</li><li>Y：<code>goal.y - tolerance</code> 到 <code>goal.y + tolerance</code>。</li><li>步长：Global Costmap Resolution。</li></ul><p>组成的正方形区域内逐点检查 Potential，并选择与原始 Goal 欧氏距离平方最小的可达点。</p><p>这里有三个容易混淆的结论：</p><ul><li>容差搜索区域是正方形采样范围，不是严格的圆形半径。</li><li>排序依据是离原目标最近，不是候选点的路径总代价最低。</li><li>找到替代终点后，输出 Path 会终止在替代点，而不是穿过障碍强行补到原目标。</li></ul><hr><h2 id="十、从-potential-array-到-path-不是沿栅格边一格一格走" tabindex="-1">十、从 Potential Array 到 Path：不是沿栅格边一格一格走 <a class="header-anchor" href="#十、从-potential-array-到-path-不是沿栅格边一格一格走" aria-label="Permalink to &quot;十、从 Potential Array 到 Path：不是沿栅格边一格一格走&quot;">​</a></h2><p><img src="'+s+'" alt="图 6：容差选点、梯度提取、末姿态与结果分支"></p><h3 id="_10-1-梯度提取" tabindex="-1">10.1 梯度提取 <a class="header-anchor" href="#_10-1-梯度提取" aria-label="Permalink to &quot;10.1 梯度提取&quot;">​</a></h3><p><code>calcPath()</code> 从真实目标开始，读取四个相邻格点的梯度，再做双线性插值。默认 <code>pathStep=0.5</code>，每次前进约半个栅格，因此 Path 点可以位于亚栅格坐标，不局限于栅格中心。</p><h3 id="_10-2-边界退化" tabindex="-1">10.2 边界退化 <a class="header-anchor" href="#_10-2-边界退化" aria-label="Permalink to &quot;10.2 边界退化&quot;">​</a></h3><p>遇到高势能边界或检测到两步振荡时，算法不再使用连续梯度，而是在八邻域中选择 Potential 最低的格点继续前进。</p><p>越界、零梯度、高势能包围或超过 <code>4 × max(size_x, size_y)</code> 个提取步数时，路径提取失败。</p><h3 id="_10-3-路径顺序还原" tabindex="-1">10.3 路径顺序还原 <a class="header-anchor" href="#_10-3-路径顺序还原" aria-label="Permalink to &quot;10.3 路径顺序还原&quot;">​</a></h3><p>NavFn 内核得到的 Path 从真实目标指向真实起点。包装层从数组尾部向头部遍历，再用 <code>mapToWorld()</code> 转回世界坐标，最终输出真实起点到目标顺序的 Path。</p><h3 id="_10-4-终点修正" tabindex="-1">10.4 终点修正 <a class="header-anchor" href="#_10-4-终点修正" aria-label="Permalink to &quot;10.4 终点修正&quot;">​</a></h3><p>离散势场的最后一个点可能没有精确落在选定目标上。<code>smoothApproachToGoal()</code> 会比较末段距离：</p><ul><li>用目标替换原末点更短：直接替换。</li><li>否则：在 Path 尾部追加目标。</li></ul><p>这一步只是修正最后接近目标的离散伪影，不是对整条 Path 做曲率平滑。</p><hr><h2 id="十一、末姿态状态-目标朝向还是最后进近方向" tabindex="-1">十一、末姿态状态：目标朝向还是最后进近方向 <a class="header-anchor" href="#十一、末姿态状态-目标朝向还是最后进近方向" aria-label="Permalink to &quot;十一、末姿态状态：目标朝向还是最后进近方向&quot;">​</a></h2><h3 id="_11-1-使用目标朝向" tabindex="-1">11.1 使用目标朝向 <a class="header-anchor" href="#_11-1-使用目标朝向" aria-label="Permalink to &quot;11.1 使用目标朝向&quot;">​</a></h3><p>默认 <code>use_final_approach_orientation=false</code>：</p><ul><li>中间路径点 Orientation 都是单位四元数。</li><li>最后一个 Pose 使用原目标或容差替代目标携带的 Orientation。</li></ul><h3 id="_11-2-使用最后进近方向" tabindex="-1">11.2 使用最后进近方向 <a class="header-anchor" href="#_11-2-使用最后进近方向" aria-label="Permalink to &quot;11.2 使用最后进近方向&quot;">​</a></h3><p>启用 <code>use_final_approach_orientation=true</code>：</p><ul><li>插件取最后一个 Pose 与倒数第二个有效 Pose 的方向。</li><li>通过 <code>atan2(dy, dx)</code> 计算最后进近航向。</li><li>最后一个 Pose Orientation 改成这段路径的切线方向。</li></ul><p>如果最后两个点完全重合，会再向前找一个点；如果 Path 只有一个 Pose，则使用 Start Orientation。</p><p>该参数解决的是“到达位置后是否还要为了目标角度旋转”，不改变 Dijkstra／A* 的 XY 搜索过程。</p><hr><h2 id="十二、当前工程里-同一个插件怎样同时变成-dijkstra-和-a" tabindex="-1">十二、当前工程里，同一个插件怎样同时变成 Dijkstra 和 A* <a class="header-anchor" href="#十二、当前工程里-同一个插件怎样同时变成-dijkstra-和-a" aria-label="Permalink to &quot;十二、当前工程里，同一个插件怎样同时变成 Dijkstra 和 A*&quot;">​</a></h2><p><code>nav2_regulated_modules</code> 配置了两个 Plugin ID，但它们加载的是同一个 C++ Type：</p><h3 id="_12-1-gridbased" tabindex="-1">12.1 <code>GridBased</code> <a class="header-anchor" href="#_12-1-gridbased" aria-label="Permalink to &quot;12.1 `GridBased`&quot;">​</a></h3><ul><li><code>plugin: nav2_navfn_planner/NavfnPlanner</code>。</li><li><code>use_astar: false</code>。</li><li>运行 Dijkstra 势场传播。</li></ul><h3 id="_12-2-gridbasedastar" tabindex="-1">12.2 <code>GridBasedAstar</code> <a class="header-anchor" href="#_12-2-gridbasedastar" aria-label="Permalink to &quot;12.2 `GridBasedAstar`&quot;">​</a></h3><ul><li><code>plugin: nav2_navfn_planner/NavfnPlanner</code>。</li><li><code>use_astar: true</code>。</li><li>运行带欧氏启发的 A* 势场传播。</li></ul><p>Planner Server 会为两个 ID 分别创建 NavfnPlanner 实例，因此它们各自持有参数和 NavFn 内核，不是一个实例反复切换。</p><p>当前配置又设置：</p><p><code>selected_planner: GridBasedAstar</code></p><p>所以自研规控导航即使在 Action Goal 里请求其他 Planner ID，Planner Server 仍优先选择 <code>GridBasedAstar</code>。</p><hr><h2 id="十三、动态参数-什么时候能改-改了影响哪一次规划" tabindex="-1">十三、动态参数：什么时候能改，改了影响哪一次规划 <a class="header-anchor" href="#十三、动态参数-什么时候能改-改了影响哪一次规划" aria-label="Permalink to &quot;十三、动态参数：什么时候能改，改了影响哪一次规划&quot;">​</a></h2><p>动态参数回调只在插件 Active 期间存在。</p><p>回调按参数类型和完整名称更新四个成员变量，并始终返回 <code>successful=true</code>。它不会：</p><ul><li>检查 <code>tolerance</code> 是否非负。</li><li>检查参数组合是否合理。</li><li>重建 NavFn 内核。</li><li>对参数读写增加插件级互斥锁。</li></ul><p>下一次进入 <code>createPlan()</code> 时会读取最新成员值。正在执行的规划如果与参数更新并发，当前实现没有提供一致快照保证。</p><hr><h2 id="十四、源码函数地图-每一层分别负责什么" tabindex="-1">十四、源码函数地图：每一层分别负责什么 <a class="header-anchor" href="#十四、源码函数地图-每一层分别负责什么" aria-label="Permalink to &quot;十四、源码函数地图：每一层分别负责什么&quot;">​</a></h2><h3 id="_14-1-navfnplanner-生命周期入口" tabindex="-1">14.1 NavfnPlanner 生命周期入口 <a class="header-anchor" href="#_14-1-navfnplanner-生命周期入口" aria-label="Permalink to &quot;14.1 NavfnPlanner 生命周期入口&quot;">​</a></h3><ul><li><code>configure()</code>：接收 Planner Server 上下文，读取参数并创建 NavFn。</li><li><code>activate()</code>：注册动态参数回调。</li><li><code>deactivate()</code>：移除动态参数回调。</li><li><code>cleanup()</code>：释放 NavFn。</li></ul><h3 id="_14-2-navfnplanner-请求入口" tabindex="-1">14.2 NavfnPlanner 请求入口 <a class="header-anchor" href="#_14-2-navfnplanner-请求入口" aria-label="Permalink to &quot;14.2 NavfnPlanner 请求入口&quot;">​</a></h3><ul><li><code>createPlan()</code>：处理尺寸变化和起终点重合，再进入常规规划。</li><li><code>isPlannerOutOfDate()</code>：比较内核数组与 Costmap 尺寸。</li><li><code>makePlan()</code>：完成地图快照、势场传播、容差选点、路径提取和末姿态处理。</li><li><code>getPlanFromPotential()</code>：调用 <code>calcPath()</code>，逆序取出内核路径并生成 PoseStamped。</li><li><code>smoothApproachToGoal()</code>：修正或追加最终目标 Pose。</li><li><code>getPointPotential()</code>：查询某个世界坐标对应的势能。</li><li><code>worldToMap()</code>／<code>mapToWorld()</code>：在世界坐标与 NavFn 亚栅格坐标之间转换。</li><li><code>clearRobotCell()</code>：把共享 Costmap 的机器人栅格清为空闲。</li><li><code>dynamicParametersCallback()</code>：按类型更新四个运行参数。</li></ul><h3 id="_14-3-navfn-势场内核" tabindex="-1">14.3 NavFn 势场内核 <a class="header-anchor" href="#_14-3-navfn-势场内核" aria-label="Permalink to &quot;14.3 NavFn 势场内核&quot;">​</a></h3><ul><li><code>setNavArr()</code>：按地图尺寸分配 Cost、Potential、Pending 和 Gradient 数组。</li><li><code>setCostmap()</code>：把 ROS Cost 编码成 NavFn Cost。</li><li><code>setStart()</code>／<code>setGoal()</code>：保存内部反转后的起终点。</li><li><code>setupNavFn()</code>／<code>initCost()</code>：重置传播状态并初始化零势能源。</li><li><code>updateCell()</code>：执行 Dijkstra 的单元势能更新。</li><li><code>updateCellAstar()</code>：执行带欧氏距离入队优先级的 A* 更新。</li><li><code>propNavFnDijkstra()</code>／<code>propNavFnAstar()</code>：驱动三个 Priority Buffer 循环。</li><li><code>calcPath()</code>：沿势能梯度提取亚栅格路径。</li><li><code>gradCell()</code>：计算并缓存单元梯度。</li></ul><p>当前头文件还声明了 <code>computePotential()</code>，但 <code>navfn_planner.cpp</code> 中没有实现，正常插件调用链也没有使用它。<code>create_nav_plan_astar()</code> 同样只保留声明，源码中的示例实现被注释；这两个符号都不是 Planner Server 运行 NavfnPlanner 的入口。</p><hr><h2 id="十五、失败返回和当前源码边界" tabindex="-1">十五、失败返回和当前源码边界 <a class="header-anchor" href="#十五、失败返回和当前源码边界" aria-label="Permalink to &quot;十五、失败返回和当前源码边界&quot;">​</a></h2><h3 id="_15-1-返回空-path-的主要情况" tabindex="-1">15.1 返回空 Path 的主要情况 <a class="header-anchor" href="#_15-1-返回空-path-的主要情况" aria-label="Permalink to &quot;15.1 返回空 Path 的主要情况&quot;">​</a></h3><ul><li>Start 离开 Global Costmap。</li><li>Goal 离开 Global Costmap。</li><li>起终点相同，但该单元是 Lethal Obstacle。</li><li>原目标不可达，容差区域内也没有可达候选点。</li><li>梯度提取越界、零梯度、陷入高势能区或路径过长。</li></ul><h3 id="_15-2-同点离图风险" tabindex="-1">15.2 同点离图风险 <a class="header-anchor" href="#_15-2-同点离图风险" aria-label="Permalink to &quot;15.2 同点离图风险&quot;">​</a></h3><p>起终点 XY 相同时，快速分支调用 <code>Costmap2D::worldToMap()</code> 后没有检查返回值，随后立即读取该栅格代价。当前 checkout 对离开地图的同点请求缺少常规分支已有的保护。</p><h3 id="_15-3-起点清障会改共享地图" tabindex="-1">15.3 起点清障会改共享地图 <a class="header-anchor" href="#_15-3-起点清障会改共享地图" aria-label="Permalink to &quot;15.3 起点清障会改共享地图&quot;">​</a></h3><p><code>clearRobotCell()</code> 在取得 Costmap Mutex 之前直接调用 <code>setCost(..., FREE_SPACE)</code>。该修改发生在共享 Global Costmap 上，并且 <code>setCost()</code> 自身不加锁。</p><h3 id="_15-4-固定容量波前缓冲区" tabindex="-1">15.4 固定容量波前缓冲区 <a class="header-anchor" href="#_15-4-固定容量波前缓冲区" aria-label="Permalink to &quot;15.4 固定容量波前缓冲区&quot;">​</a></h3><p>三个 Priority Buffer 的容量固定为 <code>10000</code>。Push 宏只有在缓冲区未满时才加入单元，满载时没有异常或警告。在超大地图或极宽波前场景中，这是需要关注的容量边界。</p><h3 id="_15-5-dijkstra-的-debug-path-cost-不可靠" tabindex="-1">15.5 Dijkstra 的 Debug Path Cost 不可靠 <a class="header-anchor" href="#_15-5-dijkstra-的-debug-path-cost-不可靠" aria-label="Permalink to &quot;15.5 Dijkstra 的 Debug Path Cost 不可靠&quot;">​</a></h3><p><code>last_path_cost_</code> 只在 A* 传播末尾赋值，但路径提取成功后两种模式都会读取它输出 Debug 日志。Dijkstra 模式下这条日志不能当成有效路径代价；它不参与 Path 计算和上层结果判断。</p><hr><h2 id="十六、排查-navfn-规划问题时-优先看这八个点" tabindex="-1">十六、排查 NavFn 规划问题时，优先看这八个点 <a class="header-anchor" href="#十六、排查-navfn-规划问题时-优先看这八个点" aria-label="Permalink to &quot;十六、排查 NavFn 规划问题时，优先看这八个点&quot;">​</a></h2><h3 id="_16-1-action-有请求-但插件没有运行" tabindex="-1">16.1 Action 有请求，但插件没有运行 <a class="header-anchor" href="#_16-1-action-有请求-但插件没有运行" aria-label="Permalink to &quot;16.1 Action 有请求，但插件没有运行&quot;">​</a></h3><p>先检查 Planner Server 是否 Active，以及请求的 Planner ID 是否实际选择到 <code>nav2_navfn_planner/NavfnPlanner</code>。</p><h3 id="_16-2-明明配置-dijkstra-却跑了-a" tabindex="-1">16.2 明明配置 Dijkstra，却跑了 A* <a class="header-anchor" href="#_16-2-明明配置-dijkstra-却跑了-a" aria-label="Permalink to &quot;16.2 明明配置 Dijkstra，却跑了 A*&quot;">​</a></h3><p>检查 <code>selected_planner</code>。它会覆盖 Action Goal 中的 <code>planner_id</code>。</p><h3 id="_16-3-起点离图" tabindex="-1">16.3 起点离图 <a class="header-anchor" href="#_16-3-起点离图" aria-label="Permalink to &quot;16.3 起点离图&quot;">​</a></h3><p>检查定位和 Global Costmap Origin／Size。NavfnPlanner 不做 TF，传入 Pose 必须已经在 Global Frame。</p><h3 id="_16-4-目标被占用仍然成功" tabindex="-1">16.4 目标被占用仍然成功 <a class="header-anchor" href="#_16-4-目标被占用仍然成功" aria-label="Permalink to &quot;16.4 目标被占用仍然成功&quot;">​</a></h3><p>检查 <code>tolerance</code>。输出终点可能是目标附近最近可达点，而不是原始目标。</p><h3 id="_16-5-路径穿过-unknown" tabindex="-1">16.5 路径穿过 Unknown <a class="header-anchor" href="#_16-5-路径穿过-unknown" aria-label="Permalink to &quot;16.5 路径穿过 Unknown&quot;">​</a></h3><p>检查 <code>allow_unknown</code>。为真时 Unknown 是高代价可通行区，不是障碍。</p><h3 id="_16-6-路径贴障碍" tabindex="-1">16.6 路径贴障碍 <a class="header-anchor" href="#_16-6-路径贴障碍" aria-label="Permalink to &quot;16.6 路径贴障碍&quot;">​</a></h3><p>NavFn 使用的是已经膨胀后的 Global Costmap。重点检查 Inflation Layer，而不是在 NavFn 中寻找机器人 Footprint 参数。</p><h3 id="_16-7-到点后机器人是否旋转不符合预期" tabindex="-1">16.7 到点后机器人是否旋转不符合预期 <a class="header-anchor" href="#_16-7-到点后机器人是否旋转不符合预期" aria-label="Permalink to &quot;16.7 到点后机器人是否旋转不符合预期&quot;">​</a></h3><p>检查 <code>use_final_approach_orientation</code>，并同时确认 Controller 的 Goal Checker 对目标角度的要求。</p><h3 id="_16-8-大地图偶发无路" tabindex="-1">16.8 大地图偶发无路 <a class="header-anchor" href="#_16-8-大地图偶发无路" aria-label="Permalink to &quot;16.8 大地图偶发无路&quot;">​</a></h3><p>除地图连通性外，还要关注 <code>PRIORITYBUFSIZE=10000</code> 和固定传播／路径提取步数上限。</p><hr><h2 id="十七、把整个包压缩成一句话" tabindex="-1">十七、把整个包压缩成一句话 <a class="header-anchor" href="#十七、把整个包压缩成一句话" aria-label="Permalink to &quot;十七、把整个包压缩成一句话&quot;">​</a></h2><p><code>nav2_navfn_planner</code> 是 Planner Server 内部的经典全局规划插件：它把 Global Costmap 转换成 NavFn 代价数组，用 Dijkstra 或 A* 从真实起点传播导航势场，再从真实目标沿势场梯度反向取路，最终还原成起点到目标的 <code>nav_msgs/Path</code>。</p><p>它的稳定来自简单清晰的二维势场模型；它的边界也同样明确：只理解 XY 栅格代价，不理解车辆运动学，不拥有 ROS 导航状态机，也不负责路径执行。</p>',218)])])}const k=e(p,[["render",u]]);export{q as __pageData,k as default};
